import json
rows=[json.loads(l) for l in open('/workspace/results/run60/metrics.jsonl')]
for r in rows:
    step=r['step']
    keys=list(r['data'].keys())
    if step%10==0 or step in (1,2,3):
        d={k:round(v,4) for k,v in r['data'].items()}
        print(step, d)
"

