import re

from verl.utils.reward_score import gsm8k


def _to_float(value):
    """Parse a numeric token, ignoring thousands separators and currency symbols."""
    if value is None:
        return None
    cleaned = str(value).replace(",", "").replace("$", "").rstrip(".")
    if cleaned in ("", "-", ".", "-."):
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def _extract_last_number(solution_str):
    """Return the last number contained in the response (same token rule as the scorer)."""
    tokens = re.findall("(\\-?[0-9\\.\\,]+)", solution_str)
    for token in reversed(tokens):
        if token not in ("", ".", "-"):
            return token
    return None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    # Extract the final answer with the same last-number rule used at evaluation
    # time, but compare numerically so that "20", "20.00" and "$20,000"-style
    # answers match the same gold answer. The upstream gsm8k.compute_score
    # compares the extracted token to the gold string, which mislabels every
    # answer whose decimal or thousands-separator formatting differs.
    answer = _extract_last_number(solution_str)
    pred = _to_float(answer)
    gold = _to_float(ground_truth)
    if pred is None or gold is None:
        return 0
    return 1.0 if pred == gold else 0.0

